  const verbs = ["умеет летать", "захватит мир", "съел мою пиццу", "смотрит на меня", "стоит 100 рублей", "светится в темноте", "играет в майнкрафт", "знает смысл жизни", "спит на потолке", "просит донат", "умеет говорить", "планирует побег", "читает мысли", "работает на ФСБ", "любит аниме", "строит дом", "копает алмазы", "взорвался", "упал в лаву", "нашел спавнер"];
  
